/**
 * Dependency-free ledger core.
 *
 * The public reducer accepts either raw UTF-8 JSONL text or an array of event
 * objects and returns the canonical summary required by the CLI.
 */

export class LedgerError extends Error {
  constructor(message) {
    super(message);
    this.name = 'LedgerError';
  }
}

const KINDS = new Set(['credit', 'debit']);

/** Compare two strings by Unicode code point (not UTF-16 code unit). */
export function compareCodePoints(a, b) {
  const ac = Array.from(a, (character) => character.codePointAt(0));
  const bc = Array.from(b, (character) => character.codePointAt(0));
  const length = Math.min(ac.length, bc.length);

  for (let index = 0; index < length; index += 1) {
    if (ac[index] !== bc[index]) {
      return ac[index] < bc[index] ? -1 : 1;
    }
  }

  return ac.length === bc.length ? 0 : ac.length < bc.length ? -1 : 1;
}

/** Validate one event record and return only its canonical fields. */
export function validateEvent(value, context = 'event') {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    throw new LedgerError(`${context}: record must be a JSON object`);
  }

  const { id, account, cents, kind } = value;

  if (typeof id !== 'string' || id.length === 0) {
    throw new LedgerError(`${context}: id must be a nonempty string`);
  }
  if (typeof account !== 'string' || account.length === 0) {
    throw new LedgerError(`${context}: account must be a nonempty string`);
  }
  if (typeof cents !== 'number' || !Number.isSafeInteger(cents) || cents < 0) {
    throw new LedgerError(
      `${context}: cents must be a nonnegative safe integer`,
    );
  }
  if (typeof kind !== 'string' || !KINDS.has(kind)) {
    throw new LedgerError(`${context}: kind must be "credit" or "debit"`);
  }

  return { id, account, cents, kind };
}

/** Parse UTF-8 JSONL text. Blank lines are ignored. */
export function parseJsonl(text) {
  if (typeof text !== 'string') {
    throw new LedgerError('input must be UTF-8 JSONL text');
  }

  const records = [];
  const lines = text.split(/\r\n|\n|\r/);

  for (let index = 0; index < lines.length; index += 1) {
    let line = lines[index];

    if (index === 0 && line.charCodeAt(0) === 0xfeff) {
      line = line.slice(1);
    }
    if (line.trim() === '') {
      continue;
    }

    let value;
    try {
      value = JSON.parse(line);
    } catch (error) {
      throw new LedgerError(
        `line ${index + 1}: malformed JSON: ${error.message}`,
      );
    }

    records.push(validateEvent(value, `line ${index + 1}`));
  }

  return records;
}

function toCentsValue(value) {
  const max = BigInt(Number.MAX_SAFE_INTEGER);
  const min = -max;
  if (value <= max && value >= min) {
    return Number(value);
  }
  // Keep exact precision for unusually large totals; the serializer emits
  // them as unquoted JSON integers.
  return value;
}

/**
 * Collapse events into the ledger summary.
 *
 * @param {string|Array<object>} input JSONL text or event objects.
 * @param {{account?: string}|string} [options] Optional account filter.
 */
export function reduceLedger(input, options = {}) {
  let events;

  if (typeof input === 'string') {
    events = parseJsonl(input);
  } else if (Array.isArray(input)) {
    events = input.map((event, index) =>
      validateEvent(event, `event ${index + 1}`),
    );
  } else {
    throw new LedgerError('expected JSONL text or an array of events');
  }

  let accountFilter;
  if (typeof options === 'string') {
    accountFilter = options;
  } else if (options !== null && typeof options === 'object') {
    accountFilter = options.account;
  } else if (options !== undefined) {
    throw new LedgerError('options must be an object or an account filter');
  }

  if (
    accountFilter !== undefined &&
    (typeof accountFilter !== 'string' || accountFilter.length === 0)
  ) {
    throw new LedgerError('account filter must be a nonempty string');
  }

  const seen = new Map();
  const balances = new Map();
  let duplicateEvents = 0;
  let net = 0n;

  for (const event of events) {
    const previous = seen.get(event.id);

    if (previous !== undefined) {
      if (
        previous.account !== event.account ||
        previous.cents !== event.cents ||
        previous.kind !== event.kind
      ) {
        throw new LedgerError(
          `conflicting records for id ${JSON.stringify(event.id)}`,
        );
      }
      duplicateEvents += 1;
      continue;
    }

    seen.set(event.id, event);

    const delta = event.kind === 'credit' ? BigInt(event.cents) : -BigInt(event.cents);
    balances.set(event.account, (balances.get(event.account) ?? 0n) + delta);
    net += delta;
  }

  let accountEntries = [...balances.entries()];
  let netTotal = net;

  if (accountFilter !== undefined) {
    accountEntries = accountEntries.filter(
      ([account]) => account === accountFilter,
    );
    netTotal = accountEntries.reduce(
      (total, [, balance]) => total + balance,
      0n,
    );
  }

  accountEntries.sort(([left], [right]) => compareCodePoints(left, right));

  return {
    uniqueEvents: seen.size,
    duplicateEvents,
    accounts: accountEntries.map(([account, balanceCents]) => ({
      account,
      balanceCents: toCentsValue(balanceCents),
    })),
    netCents: toCentsValue(netTotal),
  };
}

function formatCents(value) {
  if (typeof value === 'bigint') {
    return value.toString();
  }
  if (typeof value === 'number' && Number.isSafeInteger(value)) {
    return String(value);
  }
  throw new LedgerError(`cannot serialize non-integer cents value: ${value}`);
}

/** Serialize exactly the required output shape, preserving integer precision. */
export function serializeSummary(summary) {
  const accounts = summary.accounts
    .map(
      ({ account, balanceCents }) =>
        `{"account":${JSON.stringify(account)},"balanceCents":${formatCents(
          balanceCents,
        )}}`,
    )
    .join(',');

  return `{"uniqueEvents":${summary.uniqueEvents},"duplicateEvents":${summary.duplicateEvents},"accounts":[${accounts}],"netCents":${formatCents(
    summary.netCents,
  )}}`;
}

// Friendly aliases make the reducer easy to consume from tests or other code.
export const reducer = reduceLedger;
export const reduce = reduceLedger;
export const reduceEvents = reduceLedger;
export default reduceLedger;

#!/usr/bin/env node

import fs from 'node:fs';
import path from 'node:path';
import {
  LedgerError,
  reduceLedger,
  serializeSummary,
} from './ledger.mjs';

const USAGE =
  'Usage: node reconcile.mjs INPUT OUTPUT [--account NAME]';

function parseArgs(argv) {
  let input;
  let output;
  let account;

  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];

    if (argument === '--account') {
      if (index + 1 >= argv.length || argv[index + 1].startsWith('--')) {
        throw new LedgerError('--account requires a nonempty NAME');
      }
      account = argv[index + 1];
      index += 1;
      continue;
    }

    if (argument.startsWith('--account=')) {
      account = argument.slice('--account='.length);
      continue;
    }

    if (argument === '--help' || argument === '-h') {
      return { help: true };
    }

    if (argument.startsWith('-')) {
      throw new LedgerError(`unknown option: ${argument}`);
    }

    if (input === undefined) {
      input = argument;
    } else if (output === undefined) {
      output = argument;
    } else {
      throw new LedgerError(`unexpected extra argument: ${argument}`);
    }
  }

  if (input === undefined || output === undefined) {
    throw new LedgerError('INPUT and OUTPUT are required');
  }
  if (account !== undefined && account.length === 0) {
    throw new LedgerError('--account requires a nonempty NAME');
  }

  return { input, output, account };
}

function writeOutputAtomically(outputPath, contents) {
  const absoluteOutput = path.resolve(outputPath);
  const parent = path.dirname(absoluteOutput);
  fs.mkdirSync(parent, { recursive: true });

  const temporary = path.join(
    parent,
    `.${path.basename(absoluteOutput)}.${process.pid}.${Date.now()}.${Math.random()
      .toString(16)
      .slice(2)}.tmp`,
  );

  try {
    fs.writeFileSync(temporary, contents, { encoding: 'utf8', flag: 'wx' });
    fs.renameSync(temporary, absoluteOutput);
  } catch (error) {
    try {
      fs.unlinkSync(temporary);
    } catch {
      // The temporary file may not have been created.
    }
    throw error;
  }
}

function main(argv) {
  try {
    const args = parseArgs(argv);

    if (args.help) {
      process.stdout.write(`${USAGE}\n`);
      return;
    }

    // Read and fully validate/reduce before touching OUTPUT. An invalid input
    // therefore cannot destroy an existing output file.
    const text = fs.readFileSync(args.input, 'utf8');
    const summary = reduceLedger(text, { account: args.account });
    writeOutputAtomically(args.output, `${serializeSummary(summary)}\n`);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`reconcile: ${message}\n`);
    process.exitCode = 1;
  }
}

main(process.argv.slice(2));

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

import {
  LedgerError,
  compareCodePoints,
  parseJsonl,
  reduceLedger,
  serializeSummary,
} from './ledger.mjs';

const testDirectory = path.dirname(fileURLToPath(import.meta.url));
const cliPath = path.join(testDirectory, 'reconcile.mjs');

function makeTemporaryDirectory(t) {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'ledger-test-'));
  t.after(() => fs.rmSync(directory, { recursive: true, force: true }));
  return directory;
}

function runCli(args) {
  return spawnSync(process.execPath, [cliPath, ...args], {
    encoding: 'utf8',
    timeout: 15_000,
  });
}

function event(id, account, cents, kind) {
  return { id, account, cents, kind };
}

test('credits add and debits subtract using exact integer arithmetic', () => {
  const summary = reduceLedger([
    event('a', 'cash', 10, 'credit'),
    event('b', 'cash', 3, 'debit'),
    event('c', 'cash', 7, 'credit'),
  ]);

  assert.deepEqual(summary, {
    uniqueEvents: 3,
    duplicateEvents: 0,
    accounts: [{ account: 'cash', balanceCents: 14 }],
    netCents: 14,
  });
});

test('amounts near Number.MAX_SAFE_INTEGER remain exact', () => {
  const summary = reduceLedger([
    event('maximum', 'large', Number.MAX_SAFE_INTEGER, 'credit'),
    event('one', 'large', 1, 'debit'),
    event('two', 'large', 2, 'credit'),
  ]);

  assert.equal(summary.accounts[0].balanceCents, 9007199254740990);
  assert.equal(summary.netCents, 9007199254740990);
});

test('identical duplicate ids are counted and applied only once', () => {
  const summary = reduceLedger([
    event('same', 'alpha', 500, 'credit'),
    event('same', 'alpha', 500, 'credit'),
    event('same', 'alpha', 500, 'credit'),
    event('other', 'alpha', 25, 'debit'),
  ]);

  assert.deepEqual(summary, {
    uniqueEvents: 2,
    duplicateEvents: 2,
    accounts: [{ account: 'alpha', balanceCents: 475 }],
    netCents: 475,
  });
});

test('records with the same id but conflicting fields are invalid', () => {
  assert.throws(
    () =>
      reduceLedger([
        event('collision', 'alpha', 100, 'credit'),
        event('collision', 'alpha', 101, 'credit'),
      ]),
    (error) =>
      error instanceof LedgerError &&
      /conflicting records for id "collision"/.test(error.message),
  );

  assert.throws(
    () =>
      reduceLedger([
        event('collision', 'alpha', 100, 'credit'),
        event('collision', 'beta', 100, 'credit'),
      ]),
    LedgerError,
  );

  assert.throws(
    () =>
      reduceLedger([
        event('collision', 'alpha', 100, 'credit'),
        event('collision', 'alpha', 100, 'debit'),
      ]),
    LedgerError,
  );
});

test('accounts are sorted by Unicode code point, not UTF-16 code unit', () => {
  const summary = reduceLedger([
    event('1', '😀', 1, 'credit'),
    event('2', '\uE000', 1, 'credit'),
    event('3', '中', 1, 'credit'),
    event('4', 'é', 1, 'credit'),
    event('5', 'a', 1, 'credit'),
    event('6', 'A', 1, 'credit'),
  ]);

  assert.deepEqual(
    summary.accounts.map(({ account }) => account),
    ['A', 'a', 'é', '中', '\uE000', '😀'],
  );
  assert.equal(compareCodePoints('😀', '\uE000'), 1);
});

test('blank lines are ignored and CRLF input is accepted', () => {
  const text = [
    '',
    '{"id":"one","account":"a","cents":4,"kind":"credit"}',
    '   ',
    '\t',
    '{"id":"two","account":"a","cents":1,"kind":"debit"}',
    '',
  ].join('\r\n');

  const records = parseJsonl(text);
  assert.equal(records.length, 2);
  assert.deepEqual(reduceLedger(text), {
    uniqueEvents: 2,
    duplicateEvents: 0,
    accounts: [{ account: 'a', balanceCents: 3 }],
    netCents: 3,
  });
});

test('--account filtering limits accounts and net but not event counts', () => {
  const records = [
    event('1', 'alpha', 100, 'credit'),
    event('2', 'beta', 30, 'debit'),
    event('3', 'alpha', 5, 'debit'),
    event('1', 'alpha', 100, 'credit'),
  ];

  assert.deepEqual(reduceLedger(records, { account: 'alpha' }), {
    uniqueEvents: 3,
    duplicateEvents: 1,
    accounts: [{ account: 'alpha', balanceCents: 95 }],
    netCents: 95,
  });

  assert.deepEqual(reduceLedger(records, 'beta'), {
    uniqueEvents: 3,
    duplicateEvents: 1,
    accounts: [{ account: 'beta', balanceCents: -30 }],
    netCents: -30,
  });

  assert.deepEqual(reduceLedger(records, { account: 'missing' }), {
    uniqueEvents: 3,
    duplicateEvents: 1,
    accounts: [],
    netCents: 0,
  });
});

test('malformed and invalid records are rejected', () => {
  const invalidJsonl = [
    '{"id":',
    'null',
    '[]',
    '42',
    '"record"',
    '{}',
    '{"id":"","account":"a","cents":1,"kind":"credit"}',
    '{"id":3,"account":"a","cents":1,"kind":"credit"}',
    '{"id":"i","account":"","cents":1,"kind":"credit"}',
    '{"id":"i","account":9,"cents":1,"kind":"credit"}',
    '{"id":"i","account":"a","cents":-1,"kind":"credit"}',
    '{"id":"i","account":"a","cents":1.5,"kind":"credit"}',
    '{"id":"i","account":"a","cents":"1","kind":"credit"}',
    `{"id":"i","account":"a","cents":${
      Number.MAX_SAFE_INTEGER + 1
    },"kind":"credit"}`,
    '{"id":"i","account":"a","cents":1,"kind":"Credit"}',
    '{"id":"i","account":"a","cents":1,"kind":null}',
    '{"id":"i","account":"a","cents":1,"kind":"credit","extra":true} trailing',
  ];

  for (const text of invalidJsonl) {
    assert.throws(() => parseJsonl(text), LedgerError, text);
  }
});

test('the CLI writes the exact summary shape and creates parent directories', (t) => {
  const directory = makeTemporaryDirectory(t);
  const input = path.join(directory, 'input.jsonl');
  const output = path.join(directory, 'nested', 'deeper', 'result.json');

  fs.writeFileSync(
    input,
    [
      '{"id":"e1","account":"beta","cents":10,"kind":"credit"}',
      '{"id":"e2","account":"alpha","cents":7,"kind":"debit"}',
      '{"id":"e1","account":"beta","cents":10,"kind":"credit"}',
      '',
    ].join('\n'),
  );

  const result = runCli([input, output]);
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stderr, '');

  const text = fs.readFileSync(output, 'utf8');
  assert.match(
    text,
    /^\{"uniqueEvents":2,"duplicateEvents":1,"accounts":\[\{"account":"alpha","balanceCents":-7\},\{"account":"beta","balanceCents":10\}\],"netCents":3\}\n$/,
  );
  assert.deepEqual(JSON.parse(text), {
    uniqueEvents: 2,
    duplicateEvents: 1,
    accounts: [
      { account: 'alpha', balanceCents: -7 },
      { account: 'beta', balanceCents: 10 },
    ],
    netCents: 3,
  });
});

test('the CLI applies --account while keeping whole-input event counts', (t) => {
  const directory = makeTemporaryDirectory(t);
  const input = path.join(directory, 'input.jsonl');
  const output = path.join(directory, 'filtered.json');

  fs.writeFileSync(
    input,
    [
      '{"id":"1","account":"alpha","cents":100,"kind":"credit"}',
      '{"id":"2","account":"beta","cents":25,"kind":"credit"}',
      '{"id":"3","account":"alpha","cents":5,"kind":"debit"}',
      '{"id":"1","account":"alpha","cents":100,"kind":"credit"}',
    ].join('\n'),
  );

  const result = runCli([input, output, '--account', 'alpha']);
  assert.equal(result.status, 0, result.stderr);
  assert.deepEqual(JSON.parse(fs.readFileSync(output, 'utf8')), {
    uniqueEvents: 3,
    duplicateEvents: 1,
    accounts: [{ account: 'alpha', balanceCents: 95 }],
    netCents: 95,
  });

  const equalsForm = runCli([input, output, '--account=beta']);
  assert.equal(equalsForm.status, 0, equalsForm.stderr);
  assert.deepEqual(JSON.parse(fs.readFileSync(output, 'utf8')), {
    uniqueEvents: 3,
    duplicateEvents: 1,
    accounts: [{ account: 'beta', balanceCents: 25 }],
    netCents: 25,
  });
});

test('invalid input fails without replacing an existing output', (t) => {
  const directory = makeTemporaryDirectory(t);
  const input = path.join(directory, 'bad.jsonl');
  const output = path.join(directory, 'existing.json');
  const sentinel = '{"keep":"me"}\n';
  fs.writeFileSync(input, '{"id":"bad"\n');
  fs.writeFileSync(output, sentinel);

  const result = runCli([input, output]);

  assert.notEqual(result.status, 0);
  assert.match(result.stderr, /reconcile: line 1: malformed JSON/);
  assert.equal(fs.readFileSync(output, 'utf8'), sentinel);
});

test('conflicting duplicate ids fail without creating or replacing output', (t) => {
  const directory = makeTemporaryDirectory(t);
  const input = path.join(directory, 'conflict.jsonl');
  const output = path.join(directory, 'existing.json');
  const missingOutput = path.join(directory, 'never-created.json');
  const sentinel = 'preserve this output';

  fs.writeFileSync(
    input,
    [
      '{"id":"x","account":"alpha","cents":1,"kind":"credit"}',
      '{"id":"x","account":"alpha","cents":2,"kind":"credit"}',
    ].join('\n'),
  );
  fs.writeFileSync(output, sentinel);

  const result = runCli([input, output]);
  assert.notEqual(result.status, 0);
  assert.match(result.stderr, /conflicting records for id "x"/);
  assert.equal(fs.readFileSync(output, 'utf8'), sentinel);

  const noOutputResult = runCli([input, missingOutput]);
  assert.notEqual(noOutputResult.status, 0);
  assert.equal(fs.existsSync(missingOutput), false);
});

